<template>
 <view class="knowledge-page">
  <view class="hero"><view><text class="eyebrow">YOUR LISTENING LIBRARY</text><text class="heading">我的知识空间</text><text class="muted">把听过的片段、留下的想法与自己的资料放在一起。</text></view><NButton @click="go('/pages/my/my')">返回我的</NButton></view>
  <view v-if="!user.token" class="panel"><text>登录后建立自己的知识空间。</text><NButton @click="go('/pages/login/login')">登录 / 注册</NButton></view>
  <template v-else>
   <view class="space-bar panel"><label>当前空间 <NSelect :model-value="spaceId" :disabled="busy" :options="spaces.map(s=>({value:s.id,label:s.name}))" @update:model-value="selectSpace" /></label><view class="new-space"><input v-model="spaceName" placeholder="新空间名称" maxlength="80"/><NButton :disabled="busy" @click="createSpace">创建空间</NButton></view></view>
   <view v-if="spaceId" class="layout">
    <view class="sidebar panel"><text class="space-name">{{currentSpace?.name}}</text><text class="muted">仅本人可访问 · {{records.length}} / 100 条</text><NButton v-for="tab in tabs" :key="tab.id" :disabled="busy" :class="{selected:active===tab.id}" @click="changeTab(tab.id)">{{tab.name}}</NButton>
     <view class="ai-setting"><text>当前模型处理：{{currentSpace?.ai_enabled?'已开启':'关闭'}}</text><text class="muted">关闭时使用本地关键词检索。开启后，资料会发送至当前配置的模型服务，用于向量化与问答。私人对话不联网。</text><NButton :disabled="busy" @click="toggleAI">{{currentSpace?.ai_enabled?'关闭模型处理':'开启模型处理'}}</NButton></view>
     <NButton :disabled="busy" @click="loadSpace">刷新状态</NButton>
    </view>
    <view class="main">
     <view v-if="active==='notes'" class="panel">
      <text class="section-title">{{editing?'编辑笔记 / 书签':'记下这一刻'}}</text><view class="row"><NButton @click="draft.kind='NOTE'" :class="{selected:draft.kind==='NOTE'}">笔记</NButton><NButton @click="draft.kind='BOOKMARK'" :class="{selected:draft.kind==='BOOKMARK'}">书签</NButton></view>
      <input v-model="draft.title" placeholder="笔记标题" maxlength="120"/><textarea v-model="draft.content" placeholder="写下你的想法、摘录或想复习的问题。" maxlength="10000"/>
      <text v-if="draft.track_id" class="muted">关联声音 {{draft.track_id}} · {{Number(draft.anchor_second||0).toFixed(1)}} 秒 <NButton @click="draft.track_id=null;draft.album_id=null;draft.anchor_second=null;draft.kind='NOTE'">取消关联</NButton></text>
      <text v-else class="muted">想关联时间点？从播放器点击“记笔记 / 加书签”。</text>
      <view class="row"><NButton class="primary" :disabled="busy" @click="saveNote">{{editing?'保存修改':'保存到我的空间'}}</NButton><NButton @click="resetDraft">新建笔记</NButton></view>
     </view>
     <view v-if="active==='notes'" class="cards"><view v-for="item in notes" :key="item.id" class="panel item"><view class="item-head"><text class="section-title">{{item.title}}</text><text class="badge">{{item.kind==='BOOKMARK'?'书签':'笔记'}} · {{status(item.status)}}</text></view><text class="body-text">{{item.content||'已保存声音时间点'}}</text><text v-if="item.error_code" class="error">{{item.error_code}}</text><view class="row"><NButton @click="editNote(item)">编辑</NButton><NButton v-if="item.track_id" @click="play(item)">跳到时间点</NButton><NButton v-if="item.status==='FAILED'" @click="retry(item)">重试索引</NButton><NButton @click="remove(item)">删除</NButton></view></view><text v-if="!notes.length" class="muted">还没有笔记。可以直接记录，也可以从播放器带着时间点进入。</text></view>
     <view v-if="active==='files'" class="panel"><text class="section-title">{{editingFile?'更新私人资料':'添加私人资料'}}</text><text class="muted">MD / TXT / 文字 PDF，最大10 MB、40页、6万字。资料不会加入平台公共知识库。</text><input v-model="fileTitle" placeholder="资料标题" maxlength="120"/><FileInput :key="fileInputKey" @selected="file=$event"/><text class="muted">{{file?.name||'尚未选择文件'}}</text><view class="row"><NButton class="primary" :disabled="busy||!file" @click="upload">上传并处理</NButton><NButton v-if="editingFile" @click="editingFile=null;file=null;fileTitle='';fileInputKey++">取消更新</NButton></view></view>
     <view v-if="active==='files'" class="cards"><view v-for="item in documents" :key="item.id" class="panel item"><text class="section-title">{{item.title}}</text><text class="badge">{{status(item.status)}}</text><text class="muted">{{item.filename}} · {{item.active_revision?'已有生效版本':'尚未生效'}}</text><text v-if="item.error_code" class="error">{{item.error_code}}</text><view class="row"><NButton @click="download(item)">下载原件</NButton><NButton @click="editingFile=item.id;fileTitle=item.title;file=null;fileInputKey++">更新文件</NButton><NButton v-if="item.status==='FAILED'" @click="retry(item)">重试处理</NButton><NButton @click="remove(item)">删除</NButton></view></view><text v-if="!documents.length" class="muted">上传自己的资料，和笔记一起检索。</text></view>
     <view v-if="active==='search'" class="panel"><text class="section-title">只问我的资料</text><text class="muted">检索范围：{{currentSpace?.name}}。{{currentSpace?.ai_enabled?'使用向量与关键词检索，并核验原文引用。':'模型处理关闭：返回关键词匹配的原文，不生成模型总结。'}}</text><textarea v-model="question" placeholder="例如：我记过哪些关于宇宙文明的观点？" maxlength="2000"/><view class="row"><NButton class="primary" :disabled="busy||!question.trim()" @click="ask">查询我的空间</NButton><NButton @click="openPersonal">在听见助手中打开</NButton></view><text v-if="answer" class="body-text answer">{{answer.text}}</text><view v-for="source in answer?.sources||[]" :key="source.chunk_id" class="citation"><text class="section-title">[{{source.citation}}] {{source.title}}</text><text class="body-text">{{source.quote}}</text><view class="row"><NButton @click="locate(source)">查看资料</NButton><NButton v-if="source.link?.track_id" @click="play(source.link)">跳到声音时间点</NButton></view></view></view>
     <view v-if="active==='review'" class="panel"><text class="section-title">最近14天 · 听书回顾</text><text class="muted">{{review?.basis}}</text><text class="muted">{{review?.content_boundary}}</text><view v-for="track in review?.records||[]" :key="track.track_id" class="review-item"><text class="section-title">{{track.title}}</text><text class="muted">上报覆盖 {{track.covered_seconds}} 秒 · 最近保存位置 {{Number(track.resume_second||0).toFixed(1)}} 秒</text><text class="body-text">{{track.intervals.length?'播放区间：'+track.intervals.map(pair=>pair.map(v=>v.toFixed(1)).join('–')+'秒').join('、'):'只有保存位置，暂无连续播放区间。'}}</text><view class="row"><NButton @click="play({...track,anchor_second:track.resume_second||0})">继续收听</NButton><NButton @click="draft={kind:'NOTE',title:track.title+' · 听书笔记',content:'',track_id:track.track_id,album_id:track.album_id,anchor_second:track.resume_second||0};editing=null;active='notes'">记一条笔记</NButton></view><text v-for="note in track.notes" :key="note.id" class="body-text">我的笔记 · {{note.title}}：{{note.excerpt}}</text></view><text v-if="!review?.records?.length" class="muted">播放样例并保存后，这里会出现你的收听回顾。</text><text class="section-title">从笔记开始复习</text><view v-for="entry in review?.review_questions||[]" :key="entry.item_id" class="citation"><text>{{entry.title}}</text><text class="muted">{{entry.question}}</text><text class="body-text">{{entry.evidence}}</text></view></view>
    </view>
   </view>
   <view v-else class="panel empty"><text class="section-title">建立你的第一座知识空间</text><text class="muted">可以按“日常听书”“技术学习”等主题整理。先填写上方空间名称并创建。</text></view>
  </template>
  <view class="notice" aria-live="polite"><text v-if="message">{{message}}</text><text v-if="error" class="error">{{error}}</text></view>
 </view>
</template>
<script setup lang="ts">
import {computed,defineComponent,h,onUnmounted,ref,watch} from 'vue'
import {onLoad,onShow} from '@dcloudio/uni-app'
import {useUserStore} from '../../stores/user'
import {openAssistant,useAssistantStore} from '../../stores/assistant'
import {BASE_URL} from '../../config/confjg'
const NButton=defineComponent({inheritAttrs:false,setup(_,{attrs,slots}){return()=>h('button',{type:'button',...attrs,class:['native-button',attrs.class]},slots.default?.())}})
const NSelect=defineComponent({props:['modelValue','options'],emits:['update:modelValue'],setup(p,{emit}){return()=>h('select',{'aria-label':'当前知识空间',value:p.modelValue,onChange:(e:any)=>emit('update:modelValue',e.target.value)},p.options.map((o:any)=>h('option',{value:o.value},o.label)))}})
const FileInput=defineComponent({emits:['selected'],setup(_,{emit}){return()=>h('input',{type:'file',class:'personal-file-input',accept:'.md,.txt,.pdf','aria-label':'选择私人资料文件',onChange:(e:any)=>emit('selected',e.target.files[0])})}})
const user=useUserStore(),spaces=ref<any[]>([]),spaceId=ref(''),spaceName=ref('我的听书知识库'),records=ref<any[]>([]),active=ref('notes'),busy=ref(false),error=ref(''),message=ref(''),editing=ref<number|null>(null),editingFile=ref<number|null>(null),fileTitle=ref(''),file=ref<File|null>(null),fileInputKey=ref(0),question=ref(''),answer=ref<any>(null),review=ref<any>(null)
const draft=ref<any>({kind:'NOTE',title:'',content:'',album_id:null,track_id:null,anchor_second:null})
const tabs=[{id:'notes',name:'笔记与书签'},{id:'files',name:'我的资料'},{id:'search',name:'私人资料问答'},{id:'review',name:'听书回顾'}]
const currentSpace=computed(()=>spaces.value.find(s=>s.id===spaceId.value)),notes=computed(()=>records.value.filter(i=>i.kind!=='DOCUMENT')),documents=computed(()=>records.value.filter(i=>i.kind==='DOCUMENT'))
let options:any={},poll:any,version=0,polls=0
function go(url:string){uni.navigateTo({url})}
function path(suffix=''){return '/api/personal/spaces/'+spaceId.value+suffix}
async function api(route:string,method='GET',body?:any){const token=user.token,response=await fetch(BASE_URL+route,{method,headers:{token,...(body instanceof FormData?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body)});if(token!==user.token)throw Error('账号已变化，请刷新页面');if(!response.ok){const b=await response.json();throw Error(typeof b.detail==='string'?b.detail:'请检查输入与登录状态')}const result=await response.json();if(token!==user.token)throw Error('账号已变化，请刷新页面');return result}
async function action(fn:()=>Promise<any>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function loadSpace(){if(!spaceId.value||!user.token)return;clearTimeout(poll);const id=spaceId.value,v=++version;try{const data=await api(path('/items'));if(v!==version||id!==spaceId.value)return;records.value=data.records;spaces.value=spaces.value.map(s=>s.id===id?{...s,...data.space}:s);if(active.value==='review')review.value=await api(path('/review'));if(data.records.some((r:any)=>['QUEUED','PROCESSING','DELETING'].includes(r.status))&&polls++<40)poll=setTimeout(loadSpace,1500)}catch(e:any){if(v===version)error.value=e.message}}
async function selectSpace(value:string){version++;clearTimeout(poll);spaceId.value=value;records.value=[];review.value=null;answer.value=null;editing.value=null;editingFile.value=null;file.value=null;fileTitle.value='';fileInputKey.value++;polls=0;resetDraft();await loadSpace()}
async function createSpace(){await action(async()=>{const s=await api('/api/personal/spaces','POST',{name:spaceName.value});spaces.value=(await api('/api/personal/spaces')).records;await selectSpace(s.id);message.value='私人空间已建立。'})}
function resetDraft(){editing.value=null;draft.value={kind:options.kind==='BOOKMARK'?'BOOKMARK':'NOTE',title:options.trackId?'声音 '+options.trackId+' · '+(options.kind==='BOOKMARK'?'书签':'笔记'):'',content:'',album_id:options.albumId?Number(options.albumId):null,track_id:options.trackId?Number(options.trackId):null,anchor_second:options.trackId?Number(options.second||0):null}}
async function saveNote(){await action(async()=>{await api(path('/items'+(editing.value?'/'+editing.value:'')),editing.value?'PATCH':'POST',draft.value);resetDraft();polls=0;await loadSpace();message.value='已保存，后台正在更新私人索引。'})}
function editNote(item:any){editing.value=item.id;draft.value={kind:item.kind,title:item.title,content:item.content,album_id:item.album_id,track_id:item.track_id,anchor_second:item.anchor_second===null?null:Number(item.anchor_second)};active.value='notes';uni.pageScrollTo({scrollTop:0,duration:150})}
async function remove(item:any){const result=await uni.showModal({title:'删除私人资料',content:'删除“'+item.title+'”？删除后立即退出检索。原件和历史索引暂保留在项目存储中，不执行物理擦除。'});if(!result.confirm)return;await action(async()=>{await api(path('/items/'+item.id),'DELETE');polls=0;await loadSpace();answer.value=null;message.value='已从当前空间删除。'})}
async function retry(item:any){await action(async()=>{await api(path('/items/'+item.id+'/retry'),'POST',{});polls=0;await loadSpace()})}
async function upload(){await action(async()=>{if(!file.value)throw Error('请选择文件');if(file.value.size>10*1024*1024)throw Error('文件最大10 MB');const form=new FormData();form.set('title',fileTitle.value);form.set('file',file.value);if(editingFile.value)form.set('identity',String(editingFile.value));await api(path('/documents'),'POST',form);file.value=null;editingFile.value=null;fileTitle.value='';fileInputKey.value++;polls=0;await loadSpace();message.value='已上传，后台正在解析私人资料。'})}
async function download(item:any){await action(async()=>{const response=await fetch(BASE_URL+path('/documents/'+item.id+'/download'),{headers:{token:user.token}});if(!response.ok)throw Error('下载失败或资料已删除');const url=URL.createObjectURL(await response.blob()),anchor=document.createElement('a');anchor.href=url;anchor.download=item.filename;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
async function toggleAI(){if(!currentSpace.value)return;const enabled=!currentSpace.value.ai_enabled;if(enabled){const result=await uni.showModal({title:'允许当前模型处理此空间',content:'此空间的资料将发送至管理台配置的向量/对话模型，用于索引和问答。私人对话不启用联网搜索。是否开启？'});if(!result.confirm)return}await action(async()=>{await api(path(),'PATCH',{ai_enabled:enabled});polls=0;await loadSpace();message.value=enabled?'已开启，后台正在建立向量索引。':'已关闭，新查询使用本地关键词检索；已经发出的请求无法撤回。'})}
async function ask(){const token=user.token;await action(async()=>{const result=await api(path('/query'),'POST',{question:question.value});if(token===user.token)answer.value=result})}
async function openPersonal(){await action(async()=>{const assistant=useAssistantStore();await assistant.selectKnowledgeSpace(spaceId.value);openAssistant(true)})}
function locate(source:any){const item=records.value.find(r=>String(r.id)===source.item_id);if(!item)return;if(item.kind==='DOCUMENT'){active.value='files';editingFile.value=item.id;fileTitle.value=item.title}else editNote(item)}
function play(item:any){go('/pages/player/player?trackId='+item.track_id+'&second='+Number(item.anchor_second||0))}
async function changeTab(tab:string){active.value=tab;error.value='';if(tab==='review')await action(async()=>{review.value=await api(path('/review'))})}
function status(value:string){return ({ACTIVE:'已生效',QUEUED:'待处理',PROCESSING:'处理中',FAILED:'处理失败',DELETING:'删除中'} as any)[value]||value}
onLoad((opts:any)=>{options=opts||{};if(tabs.some(t=>t.id===options.tab))active.value=options.tab;resetDraft()})
onShow(async()=>{if(!user.token)return;await action(async()=>{spaces.value=(await api('/api/personal/spaces')).records;const requested=spaces.value.find(s=>s.id===options.space);if(requested)spaceId.value=requested.id;else if(!spaces.value.some(s=>s.id===spaceId.value))spaceId.value=spaces.value[0]?.id||'';await loadSpace();if(options.item){const item=records.value.find(r=>String(r.id)===options.item);if(item){if(item.kind==='DOCUMENT')active.value='files';else editNote(item)}}})})
watch(()=>user.token,()=>{version++;clearTimeout(poll);spaces.value=[];records.value=[];spaceId.value='';answer.value=null;review.value=null;file.value=null;fileTitle.value='';editingFile.value=null;fileInputKey.value++;question.value='';spaceName.value='我的听书知识库';message.value='';error.value='';options={};resetDraft()})
onUnmounted(()=>{version++;clearTimeout(poll)})
</script>
<style scoped>
.knowledge-page{min-height:100vh;background:#f5f6f0;padding:36px max(22px,calc((100vw - 1180px)/2)) 110px;color:#29463c;font-family:Inter,"Microsoft YaHei",sans-serif}.hero{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:10px 0 28px}.eyebrow{font-size:10px;letter-spacing:2px;color:#78927d;display:block}.heading{font-size:30px;font-weight:500;display:block;margin:12px 0}.muted{display:block;font-size:12px;line-height:1.9;color:#7d8e80;margin:8px 0}.panel{background:#fffefa;border:1px solid #dfe6d9;border-radius:18px;padding:24px;margin-bottom:18px}.space-bar{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.space-bar label{font-size:12px}.new-space,.row{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.new-space input{width:190px}.layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:22px}.sidebar{align-self:start;position:sticky;top:20px}.space-name,.section-title{display:block;font-size:16px;font-weight:500;line-height:1.8;overflow-wrap:anywhere}.sidebar :deep(.native-button){display:block;width:100%;text-align:left;margin:8px 0}.ai-setting{margin-top:28px;font-size:12px;border-top:1px solid #e0e7da;padding-top:18px}.main{min-width:0}.knowledge-page :deep(.native-button){font:inherit;font-size:12px;line-height:1.6;padding:9px 13px;color:#42664f;background:#f2f5ec;border:1px solid #d6e0d0;border-radius:9px;cursor:pointer;white-space:normal}.knowledge-page :deep(.native-button:disabled){opacity:.45;cursor:default}.knowledge-page :deep(.native-button.primary),.knowledge-page :deep(.native-button.selected){color:#fff;background:#2c5b4b;border-color:#2c5b4b}.knowledge-page :deep(.native-button:focus-visible),.knowledge-page select:focus-visible{outline:3px solid #a6c8ad;outline-offset:2px}.knowledge-page input,.knowledge-page textarea{border:1px solid #dce4d5;background:#f8f9f3;border-radius:10px;padding:12px;margin:14px 0;font-size:13px;box-sizing:border-box;height:auto}.knowledge-page textarea{height:150px;width:100%;line-height:1.8}.knowledge-page select{padding:10px;border:1px solid #dce4d5;border-radius:9px;background:#f8f9f3;margin-left:10px;max-width:280px;color:#29463c}.row{margin-top:14px}.body-text{white-space:pre-wrap;overflow-wrap:anywhere;display:block;font-size:13px;line-height:1.9;margin:10px 0}.badge{font-size:10px;background:#edf2e6;color:#6b8266;border-radius:20px;padding:5px 10px;display:inline-block}.item-head{display:flex;gap:12px;align-items:center;justify-content:space-between}.citation{padding:16px;background:#eef3e7;border:1px solid #dce6d4;border-radius:12px;margin-top:16px}.review-item{padding:18px 0;border-bottom:1px solid #e4e9dd}.answer{padding-top:20px}.error{color:#9e5441;display:block;line-height:1.8;font-size:13px}.notice{position:sticky;bottom:20px;background:#f0f4e9;border-radius:10px;font-size:13px;line-height:1.8}.notice:not(:empty){padding:12px}.empty{text-align:center;padding:60px 20px}@media(max-width:720px){.knowledge-page{padding:22px 16px 100px}.heading{font-size:25px}.hero{align-items:flex-start}.layout{grid-template-columns:1fr;gap:0}.sidebar{position:static;padding:16px}.sidebar :deep(.native-button){width:auto;display:inline-block;margin-right:6px}.ai-setting{margin-top:12px;padding-top:10px}.panel{padding:18px}.space-bar{gap:8px}.new-space{width:100%}.new-space input{flex:1;width:120px}.item-head{align-items:flex-start}.space-bar select{max-width:220px}.knowledge-page input[type="file"]{max-width:100%}}
.hero :deep(.native-button){flex-shrink:0;white-space:nowrap}.knowledge-page :deep(.personal-file-input){display:block;max-width:100%;padding:14px;background:#f4f7ed;border:1px dashed #c3d2b9;border-radius:10px;font-size:12px;color:#56744e}.knowledge-page :deep(.personal-file-input::file-selector-button){border:0;border-radius:6px;background:#e3ecd9;color:#365c41;padding:8px 12px;margin-right:12px}
</style>
